<template><section class="card p-4 my-4"><h2 class="section-title">Учёт занятий</h2><p v-if="!items.length" class="my-3 text-sm text-muted">Абонементов пока нет.</p><article v-for="s in items" :key="s.id" class="py-3 border-b border-line"><p class="font-bold">{{childById(s.child_id)?.name}} · {{groups().find(g=>g.id===s.group_id)?.title}}</p><p class="text-xs my-2">До {{formatDay(s.valid_until.slice(0,10))}} · {{labels[s.status]||s.status}}</p><dl class="grid grid-cols-2 sm:grid-cols-4 gap-2 text-sm"><div><dt>Всего</dt><dd class="font-bold">{{s.lessons_total+s.adjustments_total}}</dd></div><div><dt>Использовано</dt><dd class="font-bold">{{s.lessons_used}}</dd></div><div><dt>Зарезервировано</dt><dd class="font-bold">{{s.lessons_reserved}}</dd></div><div><dt>Доступно</dt><dd class="font-bold">{{s.lessons_available}}</dd></div></dl><p v-if="s.status==='suspended'" class="text-clay text-xs mt-2">Оплата аннулирована. История и записи сохранены. Для восстановления оплатите существующий счёт.</p></article></section></template>
<script setup lang="ts">import {computed} from 'vue';import {serverSubscriptions,useDemo} from '../shared/use-demo';import {formatDay} from '../shared/demo';const props=defineProps<{childId?:string}>();const {childById,groups}=useDemo();const items=computed(()=>serverSubscriptions.value.filter(s=>!props.childId||s.child_id===props.childId));const labels:Record<string,string>={active:'Активен',scheduled:'Действует с будущей даты',exhausted:'Использован',expired:'Истёк',suspended:'Ожидает оплаты'};</script>
